def paginate(items, page, per_page):
    # Validate inputs
    if per_page < 1:
        raise ValueError("per_page must be >= 1")
    if page < 1:
        raise ValueError("page must be >= 1")

    total_items = len(items)

    # Calculate total_pages: at least 1 (even for empty list)
    if total_items == 0:
        total_pages = 1
    else:
        # Ceiling division: (total_items + per_page - 1) // per_page
        total_pages = (total_items + per_page - 1) // per_page

    # Calculate slice indices (0-based)
    start = (page - 1) * per_page
    end = start + per_page

    # Return empty items list if page is beyond total_pages
    if page > total_pages:
        items_slice = []
    else:
        items_slice = items[start:end]

    return {
        "items": items_slice,
        "page": page,
        "total_pages": total_pages,
        "has_next": page < total_pages,
        "has_prev": page > 1,
    }
