def flatten(obj, sep="."):
    """
    Flattens a nested dictionary (and lists) into a flat dictionary with path keys.

    Args:
        obj: The object to flatten. Must be a dict.
        sep: Separator for nested keys.

    Returns:
        A flat dictionary with path keys.

    Raises:
        TypeError: If obj is not a dict.
        ValueError: If any dict key contains sep.
    """
    if not isinstance(obj, dict):
        raise TypeError("Top-level object must be a dict")

    result = {}

    def _flatten(current, path_parts):
        """Recursively flatten the object."""
        if not isinstance(current, dict):
            # If it's not a dict (including lists, primitives, etc.), it's a leaf
            if path_parts:
                key = sep.join(path_parts)
                result[key] = current
            return

        # Check if any key contains the separator
        for key in current:
            if sep in key:
                raise ValueError(f"Key '{key}' contains separator '{sep}'")
            # Convert key to string for consistency
            if not isinstance(key, str):
                raise ValueError(f"Key '{key}' must be a string")

        # Process items in order
        for key, value in current.items():
            new_path = path_parts + [key]

            # Check if value is a dict or list (to continue flattening)
            if isinstance(value, dict):
                if len(value) == 0:
                    # Empty dict is a leaf value
                    result[sep.join(new_path)] = value
                else:
                    # Recurse into the dict
                    _flatten(value, new_path)
            elif isinstance(value, list):
                if len(value) == 0:
                    # Empty list is a leaf value
                    result[sep.join(new_path)] = value
                else:
                    # Process list items
                    for idx, item in enumerate(value):
                        item_path = new_path + [str(idx)]
                        # Check if item is a dict or list
                        if isinstance(item, (dict, list)):
                            _flatten(item, item_path)
                        else:
                            # Other values are leaves
                            result[sep.join(item_path)] = item
            else:
                # Other values are leaves
                result[sep.join(new_path)] = value

    _flatten(obj, [])
    return result


def unflatten(flat, sep="."):
    """
    Unflattens a flat dictionary with path keys into a nested structure.

    Args:
        flat: A flat dictionary where keys are paths separated by sep.
        sep: Separator for nested keys.

    Returns:
        A nested dictionary/list structure.

    Raises:
        ValueError: If path segments are invalid or lists aren't dense.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    result = {}

    # Helper to check if string represents a valid non-negative integer without leading zeros
    def is_valid_index(s):
        if not s:  # empty string
            return False
        # Check for leading zeros (except for "0" itself)
        if len(s) > 1 and s[0] == '0':
            return False
        try:
            return int(s) >= 0
        except ValueError:
            return False

    # Process all paths and detect conflicts
    for key in flat:
        parts = key.split(sep)

        # Build the path step by step
        current = result
        for i, part in enumerate(parts):
            # Check if this is the last part of the path
            is_last = (i == len(parts) - 1)

            if is_last:
                # This is a leaf value - just assign it
                current[part] = flat[key]
            else:
                # We need to create a nested structure
                # Determine if next part should be dict or list
                next_part = parts[i + 1]
                is_next_index = is_valid_index(next_part)

                if is_next_index:
                    # Next part should be a list index
                    # Check if current[part] exists and is a list, or needs to be created
                    if part in current:
                        if not isinstance(current[part], list):
                            raise ValueError(f"Conflict: '{sep.join(parts[:i+1])}' is a dict but needs to be a list")
                    else:
                        current[part] = []
                else:
                    # Next part should be a dict key
                    if part in current:
                        if not isinstance(current[part], dict):
                            raise ValueError(f"Conflict: '{sep.join(parts[:i+1])}' is a list but needs to be a dict")
                    else:
                        current[part] = {}

                # Move to the next level
                current = current[part]

    # Post-process to ensure lists are dense and valid
    def validate_and_normalize(obj):
        if isinstance(obj, dict):
            # Check if this dict should be a list
            if len(obj) > 0:
                # Check if all keys are valid indices
                indices = []
                all_valid = True
                for key in obj:
                    if not is_valid_index(key):
                        all_valid = False
                        break
                    indices.append(int(key))

                if all_valid:
                    # This should be a list
                    indices.sort()
                    # Check for density: indices should be 0..n-1
                    n = len(indices)
                    expected = list(range(n))
                    if indices != expected:
                        raise ValueError("List indices are not dense: expected 0..n-1")

                    # Convert dict to list
                    result_list = [None] * n
                    for key, value in obj.items():
                        result_list[int(key)] = value
                    # Recursively process each item in the list
                    for i, item in enumerate(result_list):
                        result_list[i] = validate_and_normalize(item)
                    return result_list

            # Process as dict
            new_dict = {}
            for key, value in obj.items():
                new_dict[key] = validate_and_normalize(value)
            return new_dict
        elif isinstance(obj, list):
            # Process each item in the list
            return [validate_and_normalize(item) for item in obj]
        else:
            # Base case: primitive value
            return obj

    result = validate_and_normalize(result)

    # Final conflict check: ensure no key is a prefix of another key
    # This is handled by our path construction logic, but let's verify
    keys = list(flat.keys())
    for i in range(len(keys)):
        for j in range(i + 1, len(keys)):
            key1, key2 = keys[i], keys[j]
            parts1, parts2 = key1.split(sep), key2.split(sep)

            # Check if one is prefix of another
            min_len = min(len(parts1), len(parts2))
            if parts1[:min_len] == parts2[:min_len] and len(parts1) != len(parts2):
                raise ValueError(f"Conflicting keys '{key1}' and '{key2}'")

    return result
