                    if len(value) == 0:
                        # Empty list is a leaf value
                        result[sep.join(new_path)] = value
                    else:
                        # Process list items
                        for idx, item in enumerate(value):
                            item_path = new_path + [str(idx)]
                            if isinstance(item, (dict, list)):
                                _flatten(item, item_path)
                            else:
                                result[sep.join(item_path)] = item
                else:
                    result[sep.join(new_path)] = value
        else:
            # Not a dict, must be a leaf value
            if path_parts:
                key = sep.join(path_parts)
                result[key] = current

    _flatten(obj, [])
    return result


def unflatten(flat, sep="."):
    """
    Unflattens a flat dictionary with path keys into a nested structure.

    Args:
        flat: A flat dictionary where keys are paths separated by sep.
        sep: Separator for nested keys.

    Returns:
        A nested dictionary/list structure.

    Raises:
        ValueError: If path segments are invalid or lists aren't dense.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    # First, check for key conflicts: no key should be a prefix of another key
    keys = list(flat.keys())
    for i in range(len(keys)):
        for j in range(len(keys)):
            if i != j:
                key1, key2 = keys[i], keys[j]
                parts1, parts2 = key1.split(sep), key2.split(sep)

                # Check if key1 is a prefix of key2
                if len(parts1) < len(parts2) and parts1 == parts2[:len(parts1)]:
                    raise ValueError(f"Conflicting keys '{key1}' and '{key2}'")
                if len(parts2) < len(parts1) and parts2 == parts1[:len(parts2)]:
                    raise ValueError(f"Conflicting keys '{key1}' and '{key2}'")

    # Build the nested structure
    result = {}

    def is_valid_index(s):
        if not s:
            return False
        if s[0] == '0' and len(s) > 1:
            return False
        try:
            return int(s) >= 0
        except ValueError:
            return False

    # Process each path
    for key, value in flat.items():
        parts = key.split(sep)

        # Navigate through the structure
        current = result
        for i, part in enumerate(parts):
            if i == len(parts) - 1:
                # Last part: assign the value
                current[part] = value
            else:
                next_part = parts[i + 1]
                next_is_index = is_valid_index(next_part)

                # Determine if current[part] should be a dict or list
                if part not in current:
                    if next_is_index:
                        current[part] = []
                    else:
                        current[part] = {}

                # Move to next level
                current = current[part]

    # Validate and convert where needed
    def convert(obj):
        if isinstance(obj, dict):
            # Check if this dict should be a list
            if len(obj) == 0:
                return obj

            # Check if all keys are valid indices
            indices = []
            all_indices = True
            for k in obj:
                if not is_valid_index(k):
                    all_indices = False
                    break
                indices.append(int(k))

            if all_indices:
                indices.sort()
                # Check for density
                n = len(indices)
                if indices != list(range(n)):
                    raise ValueError("List indices are not dense")

                # Convert dict to list
                result_list = [None] * n
                for k, v in obj.items():
                    result_list[int(k)] = convert(v)
                return result_list
            else:
                # Keep as dict, recursively convert values
                new_dict = {}
                for k, v in obj.items():
                    new_dict[k] = convert(v)
                return new_dict
        elif isinstance(obj, list):
            return [convert(item) for item in obj]
        else:
            return obj

    return convert(result)
