        pos += 1
        if left:
            # Just consume right side to check syntax, but don't evaluate
            # Actually, we need to evaluate for syntax checking, but not use result
            # Since we can't know if it's valid without evaluating, and we want to avoid side effects...
            # We have to evaluate, but the result doesn't matter
            _, pos = parse_logical_and(tokens, pos, env)
            # But we need to check for syntax errors, so we do parse it
            # Actually, we can't avoid evaluating it because it might have errors
            # So we evaluate it but ignore the result
            _, pos = parse_logical_and(tokens, pos, env)
            # But we need the result, so we need to evaluate it and use it
            right, pos = parse_logical_and(tokens, pos, env)
            # Since we already know left is truthy, result is 1
            left = 1
        else:
