        if left:
            # But we need to verify the right side is syntactically correct
            # So we parse it but don't evaluate
            _, right_pos = parse_logical_and(tokens, pos, env)
            # Check if right side has syntax errors by trying to evaluate it on a dummy environment
            # Actually, the spec says we should raise errors for malformed expressions
            # So we need to validate the right side
            try:
                _, right_pos = parse_logical_and(tokens, pos, env)
                # If we get here, syntax is ok, but we don't use the result
            except (SyntaxError, NameError, ZeroDivisionError):
                # We still want to raise the error, so let it propagate
                raise
            left = 1
        else:
            # Evaluate right side
            right, pos = parse_logical_and(tokens, pos, env)
            left = 1 if right else 0

    return left, pos


def parse_logical_and(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse && expression (short-circuit)."""
    left, pos = parse_comparison(tokens, pos, env)

    while pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] == '&&':
        pos += 1

        # Short-circuit: if left is falsy, result is 0 without evaluating right
        if not left:
            # But we need to verify the right side is syntactically correct
            # So we parse it but don't evaluate
            _, right_pos = parse_comparison(tokens, pos, env)
            # Check if right side has syntax errors by trying to evaluate it on a dummy environment
            # Actually, the spec says we should raise errors for malformed expressions
            # So we need to validate the right side
            try:
                _, right_pos = parse_comparison(tokens, pos, env)
                # If we get here, syntax is ok, but we don't use the result
            except (SyntaxError, NameError, ZeroDivisionError):
                # We still want to raise the error, so let it propagate
                raise
            left = 0
        else:
            # Evaluate right side
            right, pos = parse_comparison(tokens, pos, env)
            left = 1 if right else 0

    return left, pos


def parse_comparison(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse comparison expressions: == != < <= > >=.
    Non-associative: 1 < 2 < 3 is an error.
    """
    left, pos = parse_additive(tokens, pos, env)

    if pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] in ('==', '!=', '<', '<=', '>', '>='):
        op = tokens[pos][1]
        pos += 1

        # Parse right side
        right, pos = parse_additive(tokens, pos, env)

        # Check if another comparison follows (non-associative)
        if pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] in ('==', '!=', '<', '<=', '>', '>='):
            raise SyntaxError("Chained comparison is not allowed")

        # Apply comparison
        if op == '==':
            left = 1 if left == right else 0
        elif op == '!=':
            left = 1 if left != right else 0
        elif op == '<':
            left = 1 if left < right else 0
        elif op == '<=':
            left = 1 if left <= right else 0
        elif op == '>':
            left = 1 if left > right else 0
        elif op == '>=':
            left = 1 if left >= right else 0

    return left, pos


def parse_additive(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse additive expressions: + - (left-associative)."""
    left, pos = parse_multiplicative(tokens, pos, env)

    while pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] in ('+', '-'):
        op = tokens[pos][1]
        pos += 1

        right, pos = parse_multiplicative(tokens, pos, env)

        if op == '+':
            left = left + right
        else:  # '-'
            left = left - right

    return left, pos


def parse_multiplicative(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse multiplicative expressions: * / % (left-associative)."""
    left, pos = parse_unary(tokens, pos, env)

    while pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] in ('*', '/', '%'):
        op = tokens[pos][1]
        pos += 1

        right, pos = parse_unary(tokens, pos, env)

        if op == '*':
            left = left * right
        elif op == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            # Int division when exact, else float
            if isinstance(left, int) and isinstance(right, int):
                # Check if division is exact
                if left % right == 0:
                    left = left // right
                else:
                    left = left / right
            else:
                left = left / right
        elif op == '%':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            left = left % right

    return left, pos


def parse_unary(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse unary expressions: - + ! (right-associative)."""
    if pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] in ('+', '-', '!'):
        op = tokens[pos][1]
        pos += 1

        # Parse the operand
        value, pos = parse_unary(tokens, pos, env)

        if op == '-':
            value = -value
        elif op == '+':
            # Unary plus: no-op
            pass
        elif op == '!':
            value = 1 if value == 0 else 0

        return value, pos

    return parse_power(tokens, pos, env)


def parse_power(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse power expressions: ^ (right-associative)."""
    left, pos = parse_unary_minus(tokens, pos, env)

    # Power is right-associative
    if pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] == '^':
        pos += 1

        # Right-associative: parse power recursively
        right, pos = parse_power(tokens, pos, env)

        # Compute left^right
        # Handle edge cases
        if isinstance(left, float) or isinstance(right, float):
            # Convert to float for exponentiation
            left = float(left) ** float(right)
        else:
            # Int exponentiation
            if right < 0:
                left = float(left) ** float(right)
            else:
                left = left ** right

        return left, pos

    return left, pos


def parse_unary_minus(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse unary minus binding to power, so -2^2 is -(2^2) = -4."""
    if pos < len(tokens) and tokens[pos][0] == 'OP' and tokens[pos][1] == '-':
        pos += 1
        # Parse power, but unary minus binds tighter to power
        value, pos = parse_unary_minus(tokens, pos, env)
        # But we need to handle ^ specially: -2^2 should be -(2^2), not (-2)^2
        # Our approach: parse power, then apply minus
        # But this is already handled in parse_power, which calls parse_unary_minus
        # So -2^2 becomes: unary minus, then power(2,2) => -(2^2) = -4
        return -value, pos

    return parse_atom(tokens, pos, env)


def parse_atom(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float]) -> Tuple[int | float, int]:
    """Parse atoms: literals, identifiers, function calls, parentheses."""
    if pos >= len(tokens):
        raise SyntaxError("Unexpected end of expression")

    token_type, token_val = tokens[pos]

    if token_type in ('INT', 'FLOAT'):
        pos += 1
        return token_val, pos

    if token_type == 'IDENT':
        pos += 1

        # Check if it's a function call
        if pos < len(tokens) and tokens[pos][0] == 'LPAREN':
            return parse_function_call(tokens, pos, env, token_val)

        # It's a variable
        if token_val not in env:
            raise NameError(f"Unknown variable: {token_val}")
        return env[token_val], pos

    if token_type == 'LPAREN':
        pos += 1
        expr, pos = parse_expr(tokens, pos, env)

        if pos >= len(tokens) or tokens[pos][0] != 'RPAREN':
            raise SyntaxError("Expected ')' after expression")
        pos += 1

        return expr, pos

    # Unary operators already handled, so if we get here it's an error
    raise SyntaxError(f"Unexpected token: {token_val}")


def parse_function_call(tokens: List[Tuple[str, Optional[str]]], pos: int, env: dict[str, float], func_name: str) -> Tuple[int | float, int]:
    """Parse function call: name(args...)."""
    if func_name not in ('min', 'max', 'abs'):
        raise NameError(f"Unknown function: {func_name}")

    pos += 1  # skip '('

    # Parse arguments
    args = []
    if pos < len(tokens) and tokens[pos][0] != 'RPAREN':
        expr, pos = parse_expr(tokens, pos, env)
        args.append(expr)

        while pos < len(tokens) and tokens[pos][0] == 'COMMA':
            pos += 1
            expr, pos = parse_expr(tokens, pos, env)
            args.append(expr)

    if pos >= len(tokens) or tokens[pos][0] != 'RPAREN':
        raise SyntaxError("Expected ')' in function call")
    pos += 1  # skip ')'

    # Evaluate function
    if func_name == 'abs':
        if len(args) != 1:
            raise SyntaxError(f"abs() takes exactly one argument, got {len(args)}")
        return abs(args[0]), pos

    if func_name == 'min':
        if len(args) < 1:
            raise SyntaxError(f"min() requires at least one argument, got 0")
        return min(args), pos

    if func_name == 'max':
        if len(args) < 1:
            raise SyntaxError(f"max() requires at least one argument, got 0")
        return max(args), pos

    # Should not reach here
    raise NameError(f"Unknown function: {func_name}")
