import heapq
from collections import defaultdict

def route(grid: list[str]) -> tuple[int, str] | None:
    # Validate grid
    if not grid or not isinstance(grid, list) or not all(isinstance(row, str) for row in grid):
        raise ValueError("Invalid grid format")

    if not grid:
        raise ValueError("Grid is empty")

    rows = len(grid)
    cols = len(grid[0])

    # Check for ragged rows
    for i, row in enumerate(grid):
        if len(row) != cols:
            raise ValueError("Ragged grid: rows have different lengths")

    # Find start, end, and teleport pads
    start = None
    end = None
    pads = defaultdict(list)  # letter -> [positions]

    valid_chars = set('S E # . 1 2 3 4 5 6 7 8 9 a b c d e f g h i j k l m n o p q r s t u v w x y z'.split())

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                if start is not None:
                    raise ValueError("Multiple start positions")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("Multiple end positions")
                end = (r, c)
            elif ch == '#':
                pass
            elif ch == '.':
                pass
            elif ch.isdigit():
                if ch == '0':
                    raise ValueError("Invalid digit '0' in grid")
            elif ch.islower():
                pads[ch].append((r, c))
            else:
                raise ValueError(f"Unknown character '{ch}' in grid")

    # Check for exactly one start and end
    if start is None:
        raise ValueError("No start position found")
    if end is None:
        raise ValueError("No end position found")

    # Check for valid letter pads (each letter appears 0 or 2 times)
    for letter, positions in pads.items():
        if len(positions) == 1:
            raise ValueError(f"Letter '{letter}' appears only once (teleport pad requires 0 or 2)")
        if len(positions) > 2:
            raise ValueError(f"Letter '{letter}' appears more than twice")

    # Direction vectors and move characters
    directions = [
        (1, 0, 'D'),   # Down
        (0, -1, 'L'),  # Left
        (0, 1, 'R'),   # Right
        (0, -1, 'T'),  # Teleport handled separately
        (-1, 0, 'U')   # Up
    ]

    # Helper function to get move cost
    def get_cell_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E' or ch == '.' or ch.islower():
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch == '#':
            return float('inf')  # Wall is impassable
        return float('inf')

    # Helper function to check if position is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] != '#'

    # Dijkstra with state = (row, col)
    # Priority queue: (cost, path_string, row, col)
    # path_string is kept to allow lexicographically smallest path reconstruction

    # We need to find the lexicographically smallest path among minimum cost paths
    # We'll use Dijkstra with tie-breaking on path string

    # dist[r][c] = (min_cost, lex_smallest_path)
    dist = {}

    # Initial position
    sr, sc = start
    # The start position costs 1 as per problem statement
    initial_cost = 1
    initial_path = ""

    # Priority queue: (cost, path, r, c)
    heap = [(initial_cost, initial_path, sr, sc)]
    dist[(sr, sc)] = (initial_cost, initial_path)

    # Process states
    while heap:
        cost, path, r, c = heapq.heappop(heap)

        # Skip if we have a better path already
        if (r, c) in dist and dist[(r, c)][0] < cost:
            continue

        # If we reached the end, we can return immediately since Dijkstra guarantees
        # first time we reach end is with minimal cost, and we process paths in
        # lexicographic order for same cost
        if (r, c) == end:
            return (cost, path)

        # Try normal moves: D, L, R, U (in lexicographic order as per requirement: D < L < R < T < U)
        # But note: T is teleport, which is special, so we process it separately after normal moves
        for dr, dc, move in [(1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R'), (-1, 0, 'U')]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                cell_cost = get_cell_cost(nr, nc)
                new_cost = cost + cell_cost
                new_path = path + move

                state = (nr, nc)
                if state not in dist or dist[state][0] > new_cost or (dist[state][0] == new_cost and dist[state][1] > new_path):
                    dist[state] = (new_cost, new_path)
                    heapq.heappush(heap, (new_cost, new_path, nr, nc))

        # Try teleport moves
        cell_ch = grid[r][c]
        if cell_ch.islower() and cell_ch in pads and len(pads[cell_ch]) == 2:
            positions = pads[cell_ch]
            # Find the other pad
            for pos in positions:
                if pos != (r, c):
                    tr, tc = pos
                    # Teleport costs 2
                    new_cost = cost + 2
                    new_path = path + 'T'

                    state = (tr, tc)
                    if state not in dist or dist[state][0] > new_cost or (dist[state][0] == new_cost and dist[state][1] > new_path):
                        dist[state] = (new_cost, new_path)
                        heapq.heappush(heap, (new_cost, new_path, tr, tc))

    # If we exit the loop without finding end, it's unreachable
    return None
