import re
from typing import List, Optional, Tuple


class Version:
    def __init__(self, major: int, minor: int, patch: int,
                 prerelease: Optional[str] = None,
                 build_metadata: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build_metadata = build_metadata

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            s += f"-{self.prerelease}"
        if self.build_metadata is not None:
            s += f"+{self.build_metadata}"
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return False
        # Compare ignoring build metadata
        if (self.major, self.minor, self.patch) != (other.major, other.minor, other.patch):
            return False
        # Prerelease handling: None (release) > any prerelease
        if self.prerelease is None and other.prerelease is None:
            return True
        if self.prerelease is None or other.prerelease is None:
            return False
        return self._compare_prerelease_ids(self.prerelease.split('.'), other.prerelease.split('.'))

    def __lt__(self, other):
        # Compare ignoring build metadata
        if (self.major, self.minor, self.patch) != (other.major, other.minor, other.patch):
            return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

        # Same major.minor.patch
        if self.prerelease is None and other.prerelease is None:
            return False
        if self.prerelease is None:
            return False  # release > prerelease
        if other.prerelease is None:
            return True  # prerelease < release

        # Both have prerelease: compare identifier lists
        return self._compare_prerelease_ids(self.prerelease.split('.'), other.prerelease.split('.'))

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        return other < self

    def __ge__(self, other):
        return other == self or other < self

    def _compare_prerelease_ids(self, a: List[str], b: List[str]) -> bool:
        # Compare identifier lists: shorter prefix is smaller
        for i in range(min(len(a), len(b))):
            id_a = a[i]
            id_b = b[i]

            # Check if both numeric
            a_num = id_a.isdigit() and (id_a == '0' or not id_a.startswith('0'))
            b_num = id_b.isdigit() and (id_b == '0' or not id_b.startswith('0'))

            if a_num and b_num:
                # Both numeric: compare as integers
                if int(id_a) != int(id_b):
                    return int(id_a) < int(id_b)
            elif a_num:
                # Numeric < alphanumeric
                return True
            elif b_num:
                # Alphanumeric > numeric
                return False
            else:
                # Both alphanumeric: ASCII comparison
                if id_a != id_b:
                    return id_a < id_b

        # All compared identifiers are equal; shorter is smaller
        return len(a) < len(b)


def parse(v: str) -> Version:
    """
    Parse a semantic version string according to SemVer 2.0.0.

    Args:
        v: The version string to parse.

    Returns:
        A Version object.

    Raises:
        ValueError: If the version string is invalid.
    """
    if not v:
        raise ValueError("Empty version string")

    v = v.strip()

    # Remove leading 'v' or '='
    if v and v[0] in 'v=':
        v = v[1:].strip()

    # Match the full pattern for valid SemVer
    # Must have major.minor.patch (at least major)
    # Prerelease and build metadata are optional
    pattern = r'^(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    match = re.match(pattern, v)

    if not match:
        raise ValueError(f"Invalid version string: {v}")

    major_str, minor_str, patch_str, prerelease, build_metadata = match.groups()

    # Validate major (no leading zeros except for 0 itself)
    if not major_str or (len(major_str) > 1 and major_str[0] == '0'):
        raise ValueError(f"Invalid major version: {major_str}")
    major = int(major_str)

    # Default minor and patch
    minor = 0
    if minor_str is not None:
        if not minor_str or (len(minor_str) > 1 and minor_str[0] == '0'):
            raise ValueError(f"Invalid minor version: {minor_str}")
        minor = int(minor_str)

    patch = 0
    if patch_str is not None:
