def satisfies(version: str, rng: str) -> bool:
    """
    Check if a version satisfies a range.

    Args:
        version: The version string.
        rng: The range string.

    Returns:
        True if the version satisfies the range, False otherwise.

    Raises:
        ValueError: If the version or range is invalid.
    """
    ver = parse(version)

    # Split into comparator sets by ||
    sets = rng.split('||')

    for set_str in sets:
        set_str = set_str.strip()

        # Skip empty sets (they match anything)
        if not set_str:
            return True

        # Check if the set is just '*'
        if set_str == '*':
            return True

        # Split into individual comparators by whitespace
        comparators = set_str.split()

        # If empty list or ['*'], matches everything
        if not comparators or comparators == ['*']:
            return True

        # Check for hyphen range
        if '-' in comparators:
            # Find hyphen and parse as range
            try:
                hyphen_idx = comparators.index('-')
                if hyphen_idx == 0 or hyphen_idx == len(comparators) - 1:
                    raise ValueError(f"Invalid hyphen range in: {set_str}")

                lower_str = comparators[0]
                upper_str = comparators[-1]

                # Parse lower and upper bounds
                lower_ver = parse(lower_str)
                upper_ver = parse(upper_str)

                # Handle partial upper bound: if upper_ver has less precision, make it exclusive
                # e.g., '1.2.3 - 2.3' means <2.4.0
                upper_ver_str = upper_str.strip()
                if upper_ver_str.count('.') == 0:
                    # Just major version, e.g., '2'
                    upper = Version(upper_ver.major + 1, 0, 0)
                elif upper_ver_str.count('.') == 1:
                    # Major.minor, e.g., '2.3'
                    upper = Version(upper_ver.major, upper_ver.minor + 1, 0)
                else:
                    # Full version, e.g., '2.3.4'
                    upper = Version(upper_ver.major, upper_ver.minor, upper_ver.patch + 1)

                # Lower bound: if it's partial, fill with zeros
                lower_ver_str = lower_str.strip()
                if lower_ver_str.count('.') == 0:
                    # Just major version, e.g., '1'
                    lower = Version(lower_ver.major, 0, 0)
                elif lower_ver_str.count('.') == 1:
                    # Major.minor, e.g., '1.2'
                    lower = Version(lower_ver.major, lower_ver.minor, 0)
                else:
                    lower = lower_ver

                # Check if version is in [lower, upper)
                if lower <= ver < upper:
                    return True
                continue
            except ValueError:
                # If hyphen parsing fails, fall through to normal comparator parsing
                pass

        # Check if all comparators in the set match
        all_match = True
        for comp_str in comparators:
            if comp_str == '-':
                # Skip hyphen (already handled above)
                continue
            if not _satisfies_single_comparator(comp_str, ver):
                all_match = False
                break

        if all_match:
            return True

    return False


def _satisfies_single_comparator(comp_str: str, version: Version) -> bool:
    """
    Check if a version satisfies a single comparator.
    """
    comp_str = comp_str.strip()

    if not comp_str:
        raise ValueError("Empty comparator")

    # Detect operator and version string
    op = ''
    ver_str = ''

    if comp_str.startswith('>='):
        op = '>='
        ver_str = comp_str[2:].strip()
    elif comp_str.startswith('>'):
        op = '>'
        ver_str = comp_str[1:].strip()
    elif comp_str.startswith('<='):
        op = '<='
        ver_str = comp_str[2:].strip()
    elif comp_str.startswith('<'):
        op = '<'
        ver_str = comp_str[1:].strip()
    elif comp_str.startswith('='):
        op = '='
        ver_str = comp_str[1:].strip()
    elif comp_str.startswith('~'):
        op = '~'
        ver_str = comp_str[1:].strip()
    elif comp_str.startswith('^'):
        op = '^'
        ver_str = comp_str[1:].strip()
    else:
        # No operator, assume exact match
        op = ''
        ver_str = comp_str

    # Parse the version in the comparator
    ver = parse(ver_str)

    # Handle operators
    if op == '>=':
        return version >= ver
    elif op == '>':
        return version > ver
    elif op == '<=':
        return version <= ver
    elif op == '<':
        return version < ver
    elif op == '=':
        return version == ver
    elif op == '~':
        return _satisfies_tilde(version, ver, ver_str)
    elif op == '^':
        return _satisfies_caret(version, ver, ver_str)
    else:
        # Default: exact match
        return version == ver


def _satisfies_tilde(version: Version, target: Version, target_str: str) -> bool:
    """
    Check if version satisfies a tilde range (~).
    """
    # Lower bound is the target version itself
    if version < target:
        return False

    # Determine the specificity of the target version from the string
    parts = target_str.split('.')

    if len(parts) >= 3 and parts[2] != 'x' and parts[2] != '*':
        # Full version ~X.Y.Z: upper bound is next patch version (i.e., X.(Y+1).0)
        upper = Version(target.major, target.minor + 1, 0)
    elif len(parts) >= 2 and (parts[1] != 'x' and parts[1] != '*'):
        # X.Y version ~X.Y: upper bound is next minor version (i.e., X.(Y+1).0)
        upper = Version(target.major, target.minor + 1, 0)
    else:
        # X version ~X: upper bound is next major version
        upper = Version(target.major + 1, 0, 0)

    return version < upper


def _satisfies_caret(version: Version, target: Version, target_str: str) -> bool:
    """
    Check if version satisfies a caret range (^).
    """
    # Lower bound is the target version itself
    if version < target:
        return False

    major, minor, patch = target.major, target.minor, target.patch

    # Handle 0.y.z versions specially
    if major == 0:
        if minor == 0:
            # ^0.0.z is >=0.0.z <0.0.(z+1)
            upper = Version(0, 0, patch + 1)
        else:
            # ^0.y.z is >=0.y.z <0.(y+1).0
            upper = Version(0, minor + 1, 0)
    else:
        # ^X.Y.Z is >=X.Y.Z <(X+1).0.0
        upper = Version(major + 1, 0, 0)

    return version < upper


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """
    Find the maximum version that satisfies the range.

    Args:
        versions: List of version strings.
        rng: The range string.

    Returns:
        The version string that satisfies the range and is the maximum, or None if none satisfies.

    Raises:
        ValueError: If any version or the range is invalid.
    """
    if not versions:
        return None

    # Parse all versions and track which ones satisfy
    parsed_versions = []
    for v in versions:
        parsed_versions.append((parse(v), v))

    # Filter versions that satisfy the range
    satisfying_versions = [(ver, orig) for ver, orig in parsed_versions if satisfies(orig, rng)]

    if not satisfying_versions:
        return None

    # Find maximum according to SemVer precedence
    max_ver, max_orig = max(satisfying_versions, key=lambda x: x[0])

    return max_orig
