        if not isinstance(value, int):
            raise LoadError(path, f"expected int, got {type(value).__name__}")
        return value

    def check_float(value, path):
        if isinstance(value, bool):
            raise LoadError(path, f"expected float, got bool")
        if isinstance(value, int):
            return float(value)
        if not isinstance(value, float):
            raise LoadError(path, f"expected float, got {type(value).__name__}")
        return value

    def check_str(value, path):
        if not isinstance(value, str):
            raise LoadError(path, f"expected str, got {type(value).__name__}")
        return value

    def check_bool(value, path):
        if not isinstance(value, bool):
            raise LoadError(path, f"expected bool, got {type(value).__name__}")
        return value

    def check_none(value, path):
        if value is not None:
            raise LoadError(path, f"expected None, got {type(value).__name__}")
        return None

    return {
